def shape_audit(s):
 b=s.BoundingBox();return {'valid':s.isValid(),'solids':len(s.Solids()),'faces':len(s.Faces()),'bounds_mm':[b.xmin,b.xmax,b.ymin,b.ymax,b.zmin,b.zmax],'volume_mm3':sum(v.Volume() for v in s.Solids())}
def render(s,path):
 v,tr=s.tessellate(.3);v=np.array([[a.x,a.y,a.z] for a in v]);fig=plt.figure(figsize=(7,3.8));ax=fig.add_subplot(111,projection='3d');ax.add_collection3d(Poly3DCollection(v[np.array(tr)],facecolors='#aecbd8',edgecolors='#5d7180',linewidths=.12));ax.auto_scale_xyz(*v.T);ax.set_box_aspect(np.maximum(np.ptp(v,axis=0),1));ax.view_init(25,-60);ax.set_axis_off();fig.tight_layout();fig.savefig(path,dpi=180);plt.close(fig)
