labels=['SCL2 carbon inner','SCL2 carbon center','SCL2 carbon outer','SCL4 stainless inner','SCL4 stainless center','SCL4 stainless outer'];stats=[{'label':n,'column_1_based':i+3,'minimum_C':float(a[:,i+2].min()),'maximum_C':float(a[:,i+2].max()),'maximum_at_time_s':float(a[a[:,i+2].argmax(),0]),'final_C':float(a[-1,i+2])} for i,n in enumerate(labels)]
for f in ['valve-1.svg','valve-1-zoom.svg']:
 doc=pymupdf.open(R/f);zoom=1600/doc[0].rect.width;doc[0].get_pixmap(matrix=pymupdf.Matrix(zoom,zoom)).save(T/f.replace('.svg','.png'))
cat={'collection':'Power-plant valve and carbon/stainless nozzle nonlinear transient heat conduction','source':'https://www.seamplex.com/feenox/doc/tutorials/320-thermal/','repository':'https://github.com/seamplex/feenox','revision':json.loads((R/'download-manifest.json').read_text())['revision'],'license':'GPL-3.0; original LICENSE/COPYING retained','native_CAD':'valve.brep','geometry':cad,'native_cad_FEM_trajectory_candidates':1,'FEM_history':{'original_file':'valve-1.csv','samples':len(a),'time_range_s':[float(a[0,0]),float(a[-1,0])],'columns':['time_s','imposed_internal_T_C',*labels],'fields':stats,'units':'seconds and Celsius; CAD/setup use mm','not_FEM_reference_column':'Column 2 is imposed internal temperature, not a solved field target.','no_full_saved_nodal_file':'Original mesh/valve-1.msh nodal result absent from selected repository; six source sampled FEM trajectories only.'},'setup':{'thermal':'Nonlinear temperature-dependent conductivity/diffusivity, implicit transient from initial steady state','BC':'Internal T follows published 40 to250 to40 C profile; external convection to50 C at h=1e-6 W/(mm^2 K); symmetry adiabatic','materials':'Carbon steel and stainless steel temperature-dependent source properties','source_SCL_definition_file':'valve-scl-coords.fee','requested_geometry_mesh_generation_executed':False},'original_dimensioned_drawing':False,'certified_cases':0,'new_solver_runs':0,'generated_cad':0,'model_calls':0,'limitations':['Four original BREP volumes; independent source surface/volume/SCL topology matching pending.','Only sampled histories, no full nodal mesh/result binary; time samples are not independent cases.','Original output rounded to 0.001 C; preserve source time samples and compare at same positions.','Exact original mesh and convergence evidence require review; no new mesh or solve generated.','Imposed-temperature column must not be used to inflate numerical accuracy.']};(R/'catalog.json').write_text(json.dumps(cat,indent=2)+'\n');p