# Kresling: native CAD, original Abaqus deck and separately labeled FEM curves.
R=D/'web-cad-fem-kresling-origami';base=R/'extracted-original/Supporting_Materials_Zenodo';curves=[];arrays={}
for wbfile in sorted((base/'5_EXCEL/FEA-EXP results').glob('*.xlsx')):
 w=openpyxl.load_workbook(wbfile,data_only=True,read_only=True)
 for sheet in w:
  rows=list(sheet.iter_rows(values_only=True));
  for col,tag in enumerate(rows[0]):
   if tag!='FEA':continue
   vals=[];ri=[]
   for j,row in enumerate(rows[6:],7):
    trip=list(row[col:col+3]);
    if any(isinstance(v,(float,int)) for v in trip):vals.append([float(v) if isinstance(v,(int,float)) else np.nan for v in trip]);ri.append(j)
   a=np.array(vals);assert a.ndim==2 and a.shape[1]==3;assert np.isfinite(a[:,:2]).all();key='curve_'+str(len(curves));arrays[key]=a;arrays[key+'_source_rows']=np.array(ri,dtype=np.int64);rec={'workbook':str(wbfile.relative_to(R)),'sheet':sheet.title,'source_label':rows[1][col],'source_material_label':rows[3][col+1],'source_columns':[openpyxl.utils.get_column_letter(col+i+1) for i in range(3)],'start_row':7,'last_source_row':ri[-1],'samples':len(a),'units':[rows[5][col+i] for i in range(3)],'npz_key':key,'displacement_range_mm':[float(a[:,0].min()),float(a[:,0].max())],'force_range_N':[float(a[:,1].min()),float(a[:,1].max())],'force_peak_N':float(a[:,1].max()),'stored_energy_finite_samples':int(np.isfinite(a[:,2]).sum()),'count_as_independent_CAD_pair':False};curves.append(rec)
np.savez_compressed(R/'original-FEM-curves.npz',**arrays);print('KRESLING curves',len(curves),flush=True)
fig,axes=plt.subplots(1,2,figsize=(10,3.9))
for curve in [r for r in curves if r['sheet']=='RF 0.80 DM60']:
 a=arrays[curve['npz_key']];axes[0].plot(a[:,0],a[:,1],label=curve['source_label']);mask=np.isfinite(a[:,2]);axes[1].plot(a[mask,0],a[mask,2],label=curve['source_label'])
for ax in axes:ax.set_xlabel('Source displacement u [mm]');ax.grid(alpha=.25);ax.legend(fontsize=8)
axes[0].set_ylabel('Source FEM force F [N]');axes[1].set_ylabel('Source stored energy U [N mm]');fig.suptitle('Read-only plot of published FEM workbook values; no new solve');fig.tight_layout();fig.savefig(T/'kresling-original-FEM-curve-values.png',dpi=180);plt.close(fig)
